diff --git a/src/factura.mjs b/src/factura.mjs
index 5d01137..b2d2959 100644
--- a/src/factura.mjs
+++ b/src/factura.mjs
@@ -15,7 +15,11 @@ export function calcularFactura(items) {
     if (!Number.isInteger(item.cantidad) || item.cantidad <= 0) throw new RangeError("Cantidad inválida");
     if (!Number.isInteger(item.precioUnitarioCentavos) || item.precioUnitarioCentavos < 0)
       throw new RangeError("Precio inválido: debe estar en centavos enteros");
-    totalCentavos += item.cantidad * item.precioUnitarioCentavos;
+    // RF-004: descuento opcional por línea (porcentaje entero de 0 a 100), aplicado antes del total y redondeado al centavo.
+    const descuento = item.descuentoPorcentaje ?? 0;
+    if (!Number.isInteger(descuento) || descuento < 0 || descuento > 100)
+      throw new RangeError("Descuento inválido: debe ser un porcentaje entero de 0 a 100");
+    totalCentavos += Math.round((item.cantidad * item.precioUnitarioCentavos * (100 - descuento)) / 100);
   }
   const ivaCentavos = Math.round(totalCentavos * TASA_IVA);
   return { totalCentavos, ivaCentavos, netoCentavos: totalCentavos - ivaCentavos };
diff --git a/tests/factura.test.mjs b/tests/factura.test.mjs
index fabcb45..8d310b9 100644
--- a/tests/factura.test.mjs
+++ b/tests/factura.test.mjs
@@ -30,6 +30,32 @@ test("RF-003: una factura emitida no se puede modificar", () => {
   assert.throws(() => { "use strict"; f.totalCentavos = 1; }, TypeError);
 });

+test("RF-004: descuento por línea en porcentaje (0 a 100), aplicado antes del total y redondeado al centavo", () => {
+  const conDescuento = calcularFactura([{ cantidad: 2, precioUnitarioCentavos: 1000, descuentoPorcentaje: 10 }]);
+  assert.equal(conDescuento.totalCentavos, 1800);
+  assert.equal(conDescuento.ivaCentavos, 234);
+  assert.equal(conDescuento.netoCentavos, 1566);
+
+  const sinDescuento = calcularFactura([{ cantidad: 2, precioUnitarioCentavos: 1000 }]);
+  assert.equal(sinDescuento.totalCentavos, 2000);
+
+  const redondeo = calcularFactura([{ cantidad: 1, precioUnitarioCentavos: 1005, descuentoPorcentaje: 50 }]);
+  assert.equal(redondeo.totalCentavos, 503);
+
+  const total100 = calcularFactura([{ cantidad: 3, precioUnitarioCentavos: 999, descuentoPorcentaje: 100 }]);
+  assert.equal(total100.totalCentavos, 0);
+});
+
+test("RF-004: un descuento fuera de 0 a 100 se rechaza", () => {
+  for (const descuentoPorcentaje of [-1, 101, 10.5, "10", NaN]) {
+    assert.throws(
+      () => calcularFactura([{ cantidad: 1, precioUnitarioCentavos: 1000, descuentoPorcentaje }]),
+      RangeError,
+      `descuento ${descuentoPorcentaje} debería rechazarse`,
+    );
+  }
+});
